import appearance from "./generated/bodyAppearance.json";
import type { CelestialObject, ObjectId } from "../types/celestial";

/**
 * Display appearance for bodies without a surface map: colour from measured albedo
 * and colour indices, shape inputs from measured dimensions. Every value that is not
 * measured falls back to a family default and is reported in `illustrative`.
 *
 * Inputs are generated by scripts/prepare-body-appearance.py (JPL Horizons, JPL SBDB,
 * Graykowski & Jewitt 2018, Hainaut et al. 2012, cited literature).
 */
interface MeasuredAppearance {
  albedo?: number;
  albedoSource?: string;
  axes?: number[];
  axesSource?: string;
  taxonomy?: string;
  taxonomySource?: string;
  bv?: number;
  vr?: number;
  colorClass?: string;
  colorSource?: string;
}

const MEASURED = appearance.bodies as Record<string, MeasuredAppearance>;

/** Solar colours (Holmberg et al. 2006): reflectance colours are relative to these. */
export const SOLAR_BV = 0.64;
export const SOLAR_VR = 0.354;

type Family = "C" | "B" | "S" | "X" | "V" | "D" | "comet" | "icy" | "dark-regular" | "irregular" | "tno" | "tno-red";

/** Representative albedo and colours per family; illustrative defaults, not measurements. */
const FAMILY: Record<Family, { albedo: number; bv: number; vr: number; label: string }> = {
  C: { albedo: 0.06, bv: 0.71, vr: 0.38, label: "C-type (carbonaceous)" },
  B: { albedo: 0.08, bv: 0.64, vr: 0.35, label: "B-type (blue carbonaceous)" },
  S: { albedo: 0.22, bv: 0.86, vr: 0.48, label: "S-type (stony)" },
  X: { albedo: 0.12, bv: 0.71, vr: 0.40, label: "X-complex (metallic/enstatite/primitive)" },
  V: { albedo: 0.35, bv: 0.78, vr: 0.45, label: "V-type (basaltic)" },
  D: { albedo: 0.05, bv: 0.74, vr: 0.48, label: "D-type (very red, dark)" },
  comet: { albedo: 0.04, bv: 0.78, vr: 0.46, label: "comet nucleus" },
  icy: { albedo: 0.5, bv: 0.68, vr: 0.37, label: "icy satellite" },
  "dark-regular": { albedo: 0.07, bv: 0.66, vr: 0.37, label: "dark inner satellite" },
  irregular: { albedo: 0.05, bv: 0.74, vr: 0.45, label: "irregular satellite (captured)" },
  tno: { albedo: 0.1, bv: 0.85, vr: 0.52, label: "trans-Neptunian object" },
  "tno-red": { albedo: 0.12, bv: 1.08, vr: 0.70, label: "very red trans-Neptunian object" },
};

export interface BodyAppearance {
  /** Linear-sRGB display albedo (see displayAlbedo). */
  rgb: [number, number, number];
  /** Geometric albedo used, measured or family default. */
  albedo: number;
  /** Relative semi-axes a ≥ b ≥ c, or null when no dimensions are published. */
  axes: [number, number, number] | null;
  /** Icy bodies relax to spheres at smaller sizes than rocky ones. */
  icy: boolean;
  family: string;
  sources: string[];
  /** Properties that are family defaults rather than measurements. */
  illustrative: ("albedo" | "colour" | "shape")[];
}

export interface AppearanceContext {
  /** Captured moon on a distant, inclined (ecliptic-referenced) orbit. */
  irregularOrbit?: boolean;
}

function familyOf(object: Pick<CelestialObject, "id" | "parentId" | "category">, measured: MeasuredAppearance,
  context: AppearanceContext): Family {
  const taxonomy = measured.taxonomy?.trim().toUpperCase() ?? "";
  if (taxonomy.startsWith("B")) return "B";
  if (taxonomy.startsWith("C")) return "C";
  if (taxonomy.startsWith("V")) return "V";
  if (taxonomy.startsWith("D") || taxonomy.startsWith("T")) return "D";
  if (/^[XMEP]/.test(taxonomy)) return "X";
  if (/^[SQKLA]/.test(taxonomy)) return "S";
  const category = object.category.toLowerCase();
  if (category.includes("comet")) return "comet";
  if (object.parentId === "sun") {
    if (measured.colorClass === "very red") return "tno-red";
    return /dwarf|trans-neptunian|kuiper|scattered/.test(category) ? "tno" : "S";
  }
  if (object.parentId === "pluto") return "icy";
  if (context.irregularOrbit) return "irregular";
  if (object.parentId === "mars") return "D";
  // Saturn's regular moons are icy; inner moons of Jupiter, Uranus and Neptune are dark.
  return object.parentId === "saturn" ? "icy" : "dark-regular";
}

/**
 * Compress geometric albedo into a display albedo. Ratios are kept in order but
 * reduced (exponent 0.6) so a 4 % comet and a 100 % icy moon both stay legible under
 * the same sunlight-based exposure. Anchored so p = 0.6 displays at 0.62.
 */
export function displayAlbedo(geometricAlbedo: number): number {
  const p = Math.max(0.005, Math.min(1.5, geometricAlbedo));
  return Math.min(0.9, Math.max(0.03, 0.62 * (p / 0.6) ** 0.6));
}

/**
 * Reflectance colour from Johnson-Cousins indices relative to the Sun, mapped to
 * display RGB with B ≈ blue, V ≈ green and R ≈ red, slightly desaturated (0.85) because
 * broadband filters exaggerate slopes when assigned to display primaries.
 */
export function reflectanceRgb(bv: number, vr: number, albedo: number): [number, number, number] {
  const blue = 10 ** (-0.4 * (bv - SOLAR_BV) * 0.85);
  const red = 10 ** (0.4 * (vr - SOLAR_VR) * 0.85);
  const green = displayAlbedo(albedo);
  return [green * red, green, green * blue];
}

/** V−R from B−V when only B−V is published (typical small-body colour relation). */
export function estimatedVr(bv: number): number {
  return 0.62 * bv - 0.05;
}

export function measuredAppearance(id: ObjectId): MeasuredAppearance | undefined {
  return MEASURED[id];
}

export function bodyAppearance(object: Pick<CelestialObject, "id" | "parentId" | "category">,
  context: AppearanceContext = {}): BodyAppearance {
  const measured = MEASURED[object.id] ?? {};
  const family = familyOf(object, measured, context);
  const defaults = FAMILY[family];
  const illustrative: BodyAppearance["illustrative"] = [];
  const sources = new Set<string>();
  const albedo = measured.albedo ?? defaults.albedo;
  if (measured.albedo === undefined) illustrative.push("albedo");
  else if (measured.albedoSource) sources.add(measured.albedoSource);
  let bv = defaults.bv, vr = defaults.vr;
  if (measured.bv !== undefined) {
    bv = measured.bv;
    vr = measured.vr ?? estimatedVr(measured.bv);
    if (measured.colorSource) sources.add(measured.colorSource);
  } else if (measured.colorClass === "very red") {
    bv = FAMILY["tno-red"].bv;
    vr = FAMILY["tno-red"].vr;
    if (measured.colorSource) sources.add(measured.colorSource);
  } else if (measured.taxonomy) {
    if (measured.taxonomySource) sources.add(measured.taxonomySource);
  } else illustrative.push("colour");
  const axes = measured.axes?.length === 3
    ? ([...measured.axes].sort((a, b) => b - a) as [number, number, number])
    : null;
  if (axes && measured.axesSource) sources.add(measured.axesSource);
  if (!axes) illustrative.push("shape");
  const icy = family === "icy" || family === "tno" || family === "tno-red" || family === "comet"
    || (object.parentId !== null && ["saturn", "uranus", "neptune", "pluto"].includes(object.parentId));
  return {
    rgb: reflectanceRgb(bv, vr, albedo),
    albedo,
    axes,
    icy,
    family: measured.taxonomy ? `${measured.taxonomy} (${defaults.label})` : defaults.label,
    sources: [...sources],
    illustrative,
  };
}

/** One-line provenance for the information panel. */
export function appearanceFact(appearance: BodyAppearance): string {
  const parts: string[] = [];
  parts.push(appearance.illustrative.includes("albedo")
    ? `brightness typical of a ${appearance.family} (illustrative)`
    : `geometric albedo ${appearance.albedo}`);
  if (!appearance.illustrative.includes("colour")) parts.push(`colour from measured photometry or class (${appearance.family})`);
  else parts.push("colour illustrative");
  parts.push(appearance.axes
    ? `seeded illustrative surface at measured ${appearance.axes.map((axis) => +axis.toPrecision(3)).join(" × ")} proportions`
    : "seeded illustrative shape (no shape model)");
  return `${parts.join("; ")}${appearance.sources.length ? `. Sources: ${appearance.sources.join("; ")}` : ""}.`;
}
